CREATE TABLE "Part" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "name" TEXT NOT NULL, "sku" TEXT NOT NULL, "purchasePrice" DECIMAL(18,2) NOT NULL CHECK ("purchasePrice" >= 0), "salePrice" DECIMAL(18,2) NOT NULL CHECK ("salePrice" >= 0), "minimumQuantity" INTEGER NOT NULL DEFAULT 0, UNIQUE ("organizationId","id"), UNIQUE ("organizationId","sku"));
CREATE TABLE "Stock" ("organizationId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "partId" TEXT NOT NULL, "onHand" INTEGER NOT NULL DEFAULT 0 CHECK ("onHand" >= 0), "reserved" INTEGER NOT NULL DEFAULT 0 CHECK ("reserved" >= 0 AND "reserved" <= "onHand"), PRIMARY KEY ("organizationId","branchId","partId"), FOREIGN KEY ("organizationId","branchId") REFERENCES "Branch"("organizationId","id") ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY ("organizationId","partId") REFERENCES "Part"("organizationId","id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "InventoryMovement" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "branchId" TEXT NOT NULL, "partId" TEXT NOT NULL, "orderId" TEXT, "type" TEXT NOT NULL, "quantity" INTEGER NOT NULL CHECK ("quantity" > 0), "reason" TEXT NOT NULL, "actorId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "InventoryMovement_organizationId_branchId_partId_createdAt_idx" ON "InventoryMovement"("organizationId","branchId","partId","createdAt");
CREATE TABLE "OrderPart" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "partId" TEXT NOT NULL, "quantity" INTEGER NOT NULL CHECK ("quantity" > 0), "status" TEXT NOT NULL DEFAULT 'RESERVED', "unitCost" DECIMAL(18,2) NOT NULL, "unitPrice" DECIMAL(18,2) NOT NULL, UNIQUE ("organizationId","orderId","partId"), FOREIGN KEY ("organizationId","orderId") REFERENCES "Order"("organizationId","id") ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY ("organizationId","partId") REFERENCES "Part"("organizationId","id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "kind" TEXT NOT NULL CHECK ("kind" IN ('PAYMENT','REFUND')), "amount" DECIMAL(18,2) NOT NULL CHECK ("amount" > 0), "method" TEXT NOT NULL, "originalPaymentId" TEXT, "reason" TEXT, "idempotencyKey" TEXT NOT NULL, "actorId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("organizationId","idempotencyKey"), FOREIGN KEY ("organizationId","orderId") REFERENCES "Order"("organizationId","id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Payment_organizationId_orderId_idx" ON "Payment"("organizationId","orderId");
CREATE TABLE "RepairSession" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "orderId" TEXT NOT NULL, "userId" TEXT NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "endedAt" TIMESTAMP(3), FOREIGN KEY ("organizationId","orderId") REFERENCES "Order"("organizationId","id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "RepairSession_organizationId_orderId_userId_idx" ON "RepairSession"("organizationId","orderId","userId");
CREATE UNIQUE INDEX "RepairSession_one_active_per_user" ON "RepairSession"("organizationId","userId") WHERE "endedAt" IS NULL;
CREATE TABLE "Warranty" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL, "orderId" TEXT NOT NULL UNIQUE, "startDate" TIMESTAMP(3) NOT NULL, "endDate" TIMESTAMP(3) NOT NULL, "terms" TEXT NOT NULL, FOREIGN KEY ("organizationId","orderId") REFERENCES "Order"("organizationId","id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "Warranty_organizationId_endDate_idx" ON "Warranty"("organizationId","endDate");
